{"code": """"Centralised error handling migrated from Flask to FastAPI.

Exercises: custom exception handling, centralized HTTP 404/405 handling,
manual JSON parsing to preserve Flask's request.get_json(silent=True) behavior,
and a uniform error envelope every client parses.
"""

from __future__ import annotations

from json import JSONDecodeError
from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI()

_ACCOUNTS: dict[str, dict[str, Any]] = {"a1": {"id": "a1", "balance": 100}}


class Account(BaseModel):
    id: str
    balance: int


class WithdrawRequest(BaseModel):
    model_config = ConfigDict(extra="allow")

    amount: Any = None


class WithdrawResponse(BaseModel):
    id: str
    withdrawn: int
    balance: int


class InsufficientFunds(Exception):
    def __init__(self, needed: int, available: int):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds) -> JSONResponse:
    return JSONResponse(
        status_code=409,
        content={
            "error": "insufficient_funds",
            "needed": exc.needed,
            "available": exc.available,
        },
    )


@app.exception_handler(StarletteHTTPException)
async def on_http_error(request: Request, exc: StarletteHTTPException) -> JSONResponse:
    detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
    return JSONResponse(
        status_code=exc.status_code,
        content={
            "error": "http_error",
            "status": exc.status_code,
            "message": detail,
        },
    )


@app.get("/accounts/{account_id}", response_model=Account)
async def get_account(account_id: str) -> Account | JSONResponse:
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404,
            content={"error": "not_found", "resource": "account"},
        )
    return Account.model_validate(account)


@app.post("/accounts/{account_id}/withdraw", response_model=WithdrawResponse)
async def withdraw(account_id: str, request: Request) -> WithdrawResponse | JSONResponse:
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404,
            content={"error": "not_found", "resource": "account"},
        )

    try:
        raw_data = await request.json()
    except (JSONDecodeError, ValueError):
        raw_data = {}

    if not isinstance(raw_data, dict):
        raw_data = {}

    data = WithdrawRequest.model_validate(raw_data)
    amount = data.amount

    if not isinstance(amount, int) or amount <= 0:
        return JSONResponse(status_code=400, content={"error": "bad_amount"})

    balance = int(account["balance"])
    if amount > balance:
        raise InsufficientFunds(amount, balance)

    return WithdrawResponse(
        id=account_id,
        withdrawn=amount,
        balance=balance - amount,
    )
"}

{"code": """"FastAPI migration of the token-guarded Flask blueprint."""

from typing import Any

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict


class Identity(BaseModel):
    model_config = ConfigDict(frozen=True)

    user: str
    role: str


class Note(BaseModel):
    model_config = ConfigDict(frozen=True)

    id: int
    owner: str
    text: str


class AuthError(Exception):
    def __init__(self, error: str, code: str) -> None:
        self.error = error
        self.code = code


_TOKENS: dict[str, Identity] = {"secret-token": Identity(user="ana", role="admin")}
_NOTES: dict[int, Note] = {1: Note(id=1, owner="ana", text="first")}

app = FastAPI()
api = APIRouter(prefix="/api/v1")


@app.exception_handler(AuthError)
async def auth_error_handler(request: Request, exc: AuthError) -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_401_UNAUTHORIZED,
        content={"error": exc.error, "code": exc.code},
    )


async def authenticate(
    request: Request,
    x_api_token: str | None = Header(default=None, alias="X-Api-Token"),
) -> Identity:
    if not x_api_token:
        raise AuthError("missing token", "AUTH_001")

    identity = _TOKENS.get(x_api_token)
    if identity is None:
        raise AuthError("invalid token", "AUTH_002")

    request.state.identity = identity
    return identity


async def get_json_silent(request: Request) -> Any:
    content_type = request.headers.get("content-type", "")
    media_type = content_type.split(";", 1)[0].strip().lower()
    is_json = media_type == "application/json" or (
        media_type.startswith("application/") and media_type.endswith("+json")
    )
    if not is_json:
        return None

    try:
        return await request.json()
    except Exception:
        return None


@api.get("/whoami")
async def whoami(identity: Identity = Depends(authenticate)) -> dict[str, str]:
    return {"user": identity.user, "role": identity.role}


@api.get("/notes/{note_id}")
async def get_note(note_id: int, identity: Identity = Depends(authenticate)) -> dict[str, Any] | JSONResponse:
    note = _NOTES.get(note_id)
    if note is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Not Found")

    if note.owner != identity.user:
        return JSONResponse(status_code=status.HTTP_403_FORBIDDEN, content={"error": "forbidden"})

    return note.model_dump()


@api.post("/notes")
async def create_note(request: Request, identity: Identity = Depends(authenticate)) -> JSONResponse:
    parsed = await get_json_silent(request)
    data = parsed if isinstance(parsed, dict) else {}
    text = data.get("text")

    if not text:
        return JSONResponse(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            content={"error": "text is required", "code": "VAL_001"},
        )

    return JSONResponse(
        status_code=status.HTTP_201_CREATED,
        content={"id": 2, "owner": identity.user, "text": text},
    )


app.include_router(api)
"}

{"code":""""FastAPI migration of the Flask application.

Responses intentionally include non-JSON bodies, custom headers, a 204 with no
content, and a JSON creation response with Location header.
"""

from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel

app = FastAPI()

_ROWS = [("1", "bolt", "40"), ("2", "nut", "12")]


class ErrorResponse(BaseModel):
    error: str


class ItemResponse(BaseModel):
    id: int
    name: Any


@app.get("/export.csv")
def export_csv() -> Response:
    body = "id,name,qty\n" + "\n".join(",".join(row) for row in _ROWS) + "\n"
    return Response(
        content=body,
        status_code=200,
        media_type="text/csv",
        headers={"Content-Disposition": "attachment; filename=export.csv"},
    )


@app.get("/ping")
def ping() -> Response:
    return Response(
        content="pong",
        status_code=200,
        media_type="text/plain",
        headers={"X-Service": "inventory"},
    )


@app.delete("/items/{item_id}")
def delete_item(item_id: int) -> Response:
    if item_id != 1:
        return JSONResponse(
            content=ErrorResponse(error="item not found").model_dump(),
            status_code=404,
        )
    return Response(status_code=204)


@app.post("/items")
async def create_item(request: Request) -> Response:
    try:
        data = await request.json()
    except Exception:
        data = {}

    if not isinstance(data, dict) or "name" not in data:
        return JSONResponse(
            content=ErrorResponse(error="name is required").model_dump(),
            status_code=400,
        )

    return JSONResponse(
        content=ItemResponse(id=9, name=data["name"]).model_dump(),
        status_code=201,
        headers={"Location": "/items/9"},
    )
