{"code":""""Query-string heavy search endpoint migrated from Flask to FastAPI.

Preserves Flask-style query behavior for this endpoint, including first-value
lookup for repeated scalar query parameters, getlist-style repeated values,
truthy-string booleans, and silent coercion failures.
"""

from typing import Callable, Optional, TypeVar
from urllib.parse import parse_qsl

from fastapi import FastAPI, Request
from pydantic import BaseModel

app = FastAPI()

_PRODUCTS = [
    {"id": 1, "name": "bolt", "tag": "hardware", "price": 3},
    {"id": 2, "name": "nut", "tag": "hardware", "price": 1},
    {"id": 3, "name": "manual", "tag": "docs", "price": 0},
]


class Product(BaseModel):
    id: int
    name: str
    tag: str
    price: int


class SearchEcho(BaseModel):
    q: str
    limit: Optional[int]


class SearchResponse(BaseModel):
    results: list[Product]
    count: int
    echo: SearchEcho


class FacetsResponse(BaseModel):
    tags: dict[str, int]


T = TypeVar("T")


def _query_pairs(request: Request) -> list[tuple[str, str]]:
    raw_query_string = request.scope.get("query_string", b"")
    query_string = raw_query_string.decode("latin-1")
    return parse_qsl(
        query_string,
        keep_blank_values=True,
        encoding="utf-8",
        errors="replace",
    )


def _first_arg(
    pairs: list[tuple[str, str]],
    name: str,
    default: Optional[str] = None,
) -> Optional[str]:
    for key, value in pairs:
        if key == name:
            return value
    return default


def _arg_list(pairs: list[tuple[str, str]], name: str) -> list[str]:
    return [value for key, value in pairs if key == name]


def _silent_coerce(value: Optional[str], converter: Callable[[str], T]) -> Optional[T]:
    if value is None:
        return None
    try:
        return converter(value)
    except (TypeError, ValueError):
        return None


@app.get("/search")
def search(request: Request) -> dict:
    pairs = _query_pairs(request)

    term = _first_arg(pairs, "q", "") or ""
    limit = _silent_coerce(_first_arg(pairs, "limit"), int)
    max_price = _silent_coerce(_first_arg(pairs, "max_price"), float)
    include_free_value = _first_arg(pairs, "include_free", "false") or ""
    include_free = include_free_value.lower() in ("1", "true", "yes")
    tags = _arg_list(pairs, "tag")

    rows = [p for p in _PRODUCTS if term.lower() in p["name"].lower()]
    if tags:
        rows = [p for p in rows if p["tag"] in tags]
    if max_price is not None:
        rows = [p for p in rows if p["price"] <= max_price]
    if not include_free:
        rows = [p for p in rows if p["price"] > 0]
    if limit:
        rows = rows[:limit]

    response = SearchResponse(
        results=rows,
        count=len(rows),
        echo=SearchEcho(q=term, limit=limit),
    )
    return response.model_dump()


@app.get("/facets")
def facets() -> dict:
    counts: dict[str, int] = {}
    for product in _PRODUCTS:
        counts[product["tag"]] = counts.get(product["tag"], 0) + 1

    response = FacetsResponse(tags=counts)
    return response.model_dump()
"}

{"code":""""Class-based Flask MethodView example migrated to FastAPI.

Exercises: multiple HTTP verbs on the same paths, shared state between verbs,
and FastAPI/Starlette-derived 405 responses for undeclared methods.
"""

from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, ValidationError

app = FastAPI()

_TASKS: dict[int, dict[str, Any]] = {
    1: {"id": 1, "title": "write migration", "done": False}
}


class TaskModel(BaseModel):
    id: int
    title: Any
    done: bool


class TaskListModel(BaseModel):
    tasks: list[TaskModel]


class ErrorModel(BaseModel):
    error: str


class DeleteModel(BaseModel):
    deleted: int


class TitlePayload(BaseModel):
    model_config = ConfigDict(extra="allow")

    title: Any


async def get_json_silent(request: Request) -> Any:
    try:
        data = await request.json()
    except Exception:
        return {}
    return data or {}


def error_response(message: str, status_code: int) -> JSONResponse:
    return JSONResponse(
        status_code=status_code,
        content=ErrorModel(error=message).model_dump(),
    )


@app.get("/tasks")
async def list_tasks() -> dict[str, Any]:
    return TaskListModel(tasks=list(_TASKS.values())).model_dump()


@app.post("/tasks")
async def create_task(request: Request) -> JSONResponse:
    data = await get_json_silent(request)
    try:
        payload = TitlePayload.model_validate(data)
    except ValidationError:
        return error_response("title is required", 400)

    task = TaskModel(id=2, title=payload.title, done=False)
    return JSONResponse(status_code=201, content=task.model_dump())


@app.get("/tasks/{task_id}")
async def get_task(task_id: int) -> dict[str, Any] | JSONResponse:
    task = _TASKS.get(task_id)
    if task is None:
        return error_response("task not found", 404)
    return TaskModel.model_validate(task).model_dump()


@app.put("/tasks/{task_id}")
async def update_task(task_id: int, request: Request) -> dict[str, Any] | JSONResponse:
    task = _TASKS.get(task_id)
    if task is None:
        return error_response("task not found", 404)

    data = await get_json_silent(request)
    try:
        payload = TitlePayload.model_validate(data)
    except ValidationError:
        return error_response("title is required", 400)

    return TaskModel.model_validate({**task, "title": payload.title}).model_dump()


@app.delete("/tasks/{task_id}")
async def delete_task(task_id: int) -> dict[str, int] | JSONResponse:
    if task_id not in _TASKS:
        return error_response("task not found", 404)
    return DeleteModel(deleted=task_id).model_dump()
"}

{"code":"from typing import Any

from fastapi import FastAPI, Header, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict

app = FastAPI()


class Doc(BaseModel):
    model_config = ConfigDict(extra="forbid")

    id: str
    title: str
    version: int


_DOCS: dict[str, dict[str, Any]] = {"d1": {"id": "d1", "title": "spec", "version": 3}}


def _etag(version: int) -> str:
    return f'W/"{version}"'


@app.get("/docs/{doc_id}")
def get_doc(doc_id: str) -> JSONResponse:
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(content={"error": "doc not found"}, status_code=404)

    validated_doc = Doc.model_validate(doc)
    return JSONResponse(
        content=validated_doc.model_dump(),
        status_code=200,
        headers={"ETag": _etag(validated_doc.version)},
    )


@app.patch("/docs/{doc_id}")
async def patch_doc(
    doc_id: str,
    request: Request,
    if_match: str | None = Header(default=None, alias="If-Match"),
) -> JSONResponse:
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(content={"error": "doc not found"}, status_code=404)

    current_doc = Doc.model_validate(doc)

    if not if_match:
        return JSONResponse(
            content={"error": "If-Match header is required", "code": "PRECONDITION_REQUIRED"},
            status_code=428,
        )

    if if_match != _etag(current_doc.version):
        return JSONResponse(
            content={"error": "version conflict", "expected": current_doc.version},
            status_code=409,
        )

    try:
        data = await request.json()
    except Exception:
        data = {}

    if not isinstance(data, dict):
        data = {}

    title = data.get("title")
    if not isinstance(title, str) or not title:
        return JSONResponse(content={"error": "title must be a non-empty string"}, status_code=400)

    updated_doc = Doc.model_validate({**doc, "title": title, "version": current_doc.version + 1})
    return JSONResponse(
        content=updated_doc.model_dump(),
        status_code=200,
        headers={"ETag": _etag(updated_doc.version)},
    )
"}

{"code": """"Bulk endpoint returning multi-status. Synthetic case for this benchmark.

Exercises: a JSON *array* request body (not an object), per-item outcomes, HTTP
207, and a partial-failure path that still returns 2xx.
"""

from __future__ import annotations

import json
from typing import Any, Literal

from fastapi import FastAPI, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

_KNOWN = {"a", "b", "c"}


class ErrorResponse(BaseModel):
    error: str


class BulkVerifyResult(BaseModel):
    index: int
    status: Literal["invalid", "ok", "unknown"]
    reason: str | None = None


class BulkVerifyResponse(BaseModel):
    results: list[BulkVerifyResult]
    failed: int


class LimitsResponse(BaseModel):
    max_items: int
    known: list[str]


def _is_json_content_type(request: Request) -> bool:
    content_type = request.headers.get("content-type")
    if not content_type:
        return False

    mimetype = content_type.split(";", 1)[0].strip().lower()
    return mimetype == "application/json" or (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    )


async def _get_json_flask_silent(request: Request) -> Any | None:
    """Approximate Flask's request.get_json(silent=True) behavior."""
    if not _is_json_content_type(request):
        return None

    body = await request.body()
    if not body:
        return None

    try:
        return json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None


def _json_response(model: BaseModel, status_code: int = status.HTTP_200_OK) -> JSONResponse:
    return JSONResponse(
        content=model.model_dump(mode="json", exclude_none=True),
        status_code=status_code,
    )


@app.post("/bulk/verify")
async def bulk_verify(request: Request) -> JSONResponse:
    payload = await _get_json_flask_silent(request)
    if payload is None:
        return _json_response(
            ErrorResponse(error="body must be JSON"),
            status_code=status.HTTP_400_BAD_REQUEST,
        )
    if not isinstance(payload, list):
        return _json_response(
            ErrorResponse(error="body must be a JSON array"),
            status_code=status.HTTP_400_BAD_REQUEST,
        )
    if not payload:
        return _json_response(
            ErrorResponse(error="array must not be empty"),
            status_code=status.HTTP_400_BAD_REQUEST,
        )

    results: list[BulkVerifyResult] = []
    for index, key in enumerate(payload):
        if not isinstance(key, str):
            results.append(
                BulkVerifyResult(index=index, status="invalid", reason="not a string")
            )
        elif key in _KNOWN:
            results.append(BulkVerifyResult(index=index, status="ok"))
        else:
            results.append(BulkVerifyResult(index=index, status="unknown"))

    failed = sum(1 for result in results if result.status != "ok")
    response_status = status.HTTP_200_OK if failed == 0 else status.HTTP_207_MULTI_STATUS
    return _json_response(
        BulkVerifyResponse(results=results, failed=failed),
        status_code=response_status,
    )


@app.get("/bulk/limits", response_model=LimitsResponse)
def limits() -> LimitsResponse:
    return LimitsResponse(max_items=100, known=sorted(_KNOWN))
"}

{"code": """"Trailing-slash and redirect behaviour migrated from Flask to FastAPI."""

from typing import List

from fastapi import FastAPI, Request
from fastapi.responses import RedirectResponse
from pydantic import BaseModel, ConfigDict

app = FastAPI(redirect_slashes=False)


class ReportsResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    reports: List[str]


class StatusResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    status: str


class JobsResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    jobs: List[str]


class QueueResponse(BaseModel):
    model_config = ConfigDict(extra="forbid")

    queue: str
    depth: int


@app.get("/reports", include_in_schema=False)
def reports_redirect(request: Request) -> RedirectResponse:
    # Flask redirects /reports to /reports/ for a route declared with a trailing slash.
    target_url = request.url.replace(path=f"{request.url.path}/")
    return RedirectResponse(url=str(target_url), status_code=308)


@app.get("/reports/", response_model=ReportsResponse)
def list_reports() -> ReportsResponse:
    # Declared WITH a trailing slash: /reports redirects above; /reports/ returns JSON.
    return ReportsResponse(reports=["daily", "weekly"])


@app.get("/status", response_model=StatusResponse)
def status() -> StatusResponse:
    # Declared WITHOUT a trailing slash: /status/ remains 404 because redirect_slashes=False.
    return StatusResponse(status="up")


@app.get("/jobs", response_model=JobsResponse)
@app.get("/jobs/", response_model=JobsResponse, include_in_schema=False)
def jobs() -> JobsResponse:
    # Flask strict_slashes=False accepts both /jobs and /jobs/.
    return JobsResponse(jobs=[])


@app.get("/queue/{name}", response_model=QueueResponse)
def queue(name: str) -> QueueResponse:
    return QueueResponse(queue=name, depth=0)
"}

