{"code": "from __future__ import annotations

from typing import Any

from fastapi import FastAPI, Request, Response, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict

app = FastAPI()

TODOS: dict[str, dict[str, str | None]] = {
    "todo1": {"task": "build an API"},
    "todo2": {"task": "?????"},
    "todo3": {"task": "profit!"},
}


class TodoNotFound(Exception):
    def __init__(self, todo_id: str) -> None:
        self.todo_id = todo_id
        super().__init__(f"Todo {todo_id} doesn't exist")


class TodoPayload(BaseModel):
    model_config = ConfigDict(extra="ignore")

    task: str | None = None


@app.exception_handler(TodoNotFound)
async def todo_not_found_handler(request: Request, exc: TodoNotFound) -> JSONResponse:
    return JSONResponse(status_code=status.HTTP_404_NOT_FOUND, content={"message": str(exc)})


def abort_if_todo_doesnt_exist(todo_id: str) -> None:
    if todo_id not in TODOS:
        raise TodoNotFound(todo_id)


async def parse_args(request: Request) -> TodoPayload:
    data: dict[str, Any] = {}
    content_type = request.headers.get("content-type", "")

    if "application/json" in content_type:
        try:
            body = await request.json()
        except Exception:
            body = None
        if isinstance(body, dict):
            data.update(body)
    elif (
        "application/x-www-form-urlencoded" in content_type
        or "multipart/form-data" in content_type
    ):
        form = await request.form()
        data.update(dict(form))

    if "task" not in data and "task" in request.query_params:
        data["task"] = request.query_params["task"]

    return TodoPayload.model_validate(data)


@app.get("/todos/{todo_id}")
async def get_todo(todo_id: str) -> dict[str, str | None]:
    abort_if_todo_doesnt_exist(todo_id)
    return TODOS[todo_id]


@app.delete("/todos/{todo_id}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_todo(todo_id: str) -> Response:
    abort_if_todo_doesnt_exist(todo_id)
    del TODOS[todo_id]
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@app.put("/todos/{todo_id}", status_code=status.HTTP_201_CREATED)
async def put_todo(todo_id: str, request: Request) -> dict[str, str | None]:
    args = await parse_args(request)
    task = {"task": args.task}
    TODOS[todo_id] = task
    return task


@app.get("/todos")
async def get_todos() -> dict[str, dict[str, str | None]]:
    return TODOS


@app.post("/todos", status_code=status.HTTP_201_CREATED)
async def post_todo(request: Request) -> dict[str, str | None]:
    args = await parse_args(request)
    todo_id = "todo%d" % (len(TODOS) + 1)
    TODOS[todo_id] = {"task": args.task}
    return TODOS[todo_id]


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="127.0.0.1", port=8000)
"}

{"code": """"Order lifecycle with idempotency migrated from Flask to FastAPI."""

import json
from typing import Any, Dict, Optional

from fastapi import FastAPI, Query, Request
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel, ConfigDict, computed_field

app = FastAPI()

TRANSITIONS = {
    "draft": ["submitted", "cancelled"],
    "submitted": ["approved", "rejected", "cancelled"],
    "approved": ["fulfilled"],
    "rejected": [],
    "cancelled": [],
    "fulfilled": [],
}
TERMINAL = {"rejected", "cancelled", "fulfilled"}

_ORDERS: Dict[str, Dict[str, Any]] = {
    "o1": {"id": "o1", "state": "draft", "total": 30, "lines": 2},
    "o2": {"id": "o2", "state": "approved", "total": 90, "lines": 5},
}
_IDEMPOTENCY: Dict[str, Dict[str, Any]] = {}
_NEXT = [3]


class OrderPresentation(BaseModel):
    model_config = ConfigDict(extra="allow")

    id: Any
    state: Any
    total: Any
    lines: Any

    @computed_field
    @property
    def terminal(self) -> bool:
        return self.state in TERMINAL


def _present(order: Dict[str, Any]) -> Dict[str, Any]:
    # `terminal` is computed on read and stored nowhere.
    return OrderPresentation.model_validate(order).model_dump()


def _is_json_content_type(content_type: str) -> bool:
    mimetype = content_type.split(";", 1)[0].strip().lower()
    return mimetype == "application/json" or (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    )


async def _get_json_silent(request: Request) -> Any:
    # Mirrors Flask's request.get_json(silent=True): if the request is not JSON,
    # or if parsing fails, behave as though there was no JSON body.
    if not _is_json_content_type(request.headers.get("content-type", "")):
        return {}
    try:
        return await request.json()
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {}


@app.get("/orders/{order_id}")
async def get_order(order_id: str) -> JSONResponse:
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)
    return JSONResponse(_present(order))


@app.post("/orders")
async def create_order(request: Request) -> JSONResponse:
    body = await _get_json_silent(request) or {}
    total = body.get("total")
    if not isinstance(total, int) or total <= 0:
        return JSONResponse({"error": "total must be a positive integer"}, status_code=400)

    key = request.headers.get("Idempotency-Key")
    if key:
        seen = _IDEMPOTENCY.get(key)
        if seen is not None:
            if seen["total"] != total:
                return JSONResponse(
                    {
                        "error": "idempotency key reused with a different body",
                        "code": "IDEMPOTENCY_MISMATCH",
                    },
                    status_code=422,
                )
            # Replay: the original resource, and 200 rather than 201.
            return JSONResponse(_present(_ORDERS[seen["id"]]), status_code=200)

    order_id = f"o{_NEXT[0]}"
    _NEXT[0] += 1
    order = {
        "id": order_id,
        "state": "draft",
        "total": total,
        "lines": body.get("lines", 1),
    }
    _ORDERS[order_id] = order
    if key:
        _IDEMPOTENCY[key] = {"id": order_id, "total": total}

    return JSONResponse(
        _present(order),
        status_code=201,
        headers={"Location": f"/orders/{order_id}"},
    )


@app.post("/orders/{order_id}/transition")
async def transition(order_id: str, request: Request) -> JSONResponse:
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)

    body = await _get_json_silent(request) or {}
    target = body.get("to")
    if not target:
        return JSONResponse({"error": "to is required"}, status_code=400)
    if target not in TRANSITIONS:
        # Not a state at all: the client sent nonsense.
        return JSONResponse({"error": "unknown state", "state": target}, status_code=400)

    allowed = TRANSITIONS[order["state"]]
    if target not in allowed:
        # A real state, just not reachable from here.
        return JSONResponse(
            {
                "error": "illegal transition",
                "from": order["state"],
                "to": target,
                "allowed": allowed,
            },
            status_code=409,
        )

    order["state"] = target
    return JSONResponse(_present(order))


@app.delete("/orders/{order_id}")
async def delete_order(order_id: str) -> Response:
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)
    if order["state"] != "draft":
        return JSONResponse(
            {
                "error": "only draft orders can be deleted",
                "state": order["state"],
                "code": "NOT_DELETABLE",
            },
            status_code=409,
        )
    return Response(status_code=204)


@app.get("/orders")
async def list_orders(state: Optional[str] = Query(default=None)) -> JSONResponse:
    rows = list(_ORDERS.values())
    if state:
        if state not in TRANSITIONS:
            return JSONResponse({"error": "unknown state", "state": state}, status_code=400)
        rows = [order for order in rows if order["state"] == state]
    return JSONResponse({"orders": [_present(order) for order in rows], "count": len(rows)})
"}

{"code": "from __future__ import annotations

import json
from json import JSONDecodeError
from typing import Any

from fastapi import FastAPI, Request, Response
from pydantic import RootModel

app = FastAPI(redirect_slashes=False)

_USERS = {"u1": {"id": "u1", "name": "ana", "tier": "pro"}}
_BALANCES = {"u1": 50}
DEPRECATION = "version=1; sunset=2027-01-01"


class RawJson(RootModel[Any]):
    pass


def _is_json_request(request: Request) -> bool:
    content_type = request.headers.get("content-type", "")
    media_type = content_type.split(";", 1)[0].strip().lower()
    return media_type == "application/json" or (
        media_type.startswith("application/") and media_type.endswith("+json")
    )


async def _get_json_silent(request: Request) -> Any:
    if not _is_json_request(request):
        return None
    try:
        parsed = await request.json()
    except (JSONDecodeError, UnicodeDecodeError, ValueError):
        return None
    return RawJson.model_validate(parsed).root


def _json_response(content: Any, status_code: int = 200) -> Response:
    body = json.dumps(
        content,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ) + "\n"
    return Response(content=body, status_code=status_code, media_type="application/json")


def _v1_headers(response: Response) -> Response:
    response.headers["X-API-Deprecation"] = DEPRECATION
    return response


@app.get("/v1/users/{user_id}")
def v1_get_user(user_id: str) -> Response:
    user = _USERS.get(user_id, {})
    return _v1_headers(_json_response(user, 200))


@app.get("/v2/users/{user_id}")
def v2_get_user(user_id: str) -> Response:
    user = _USERS.get(user_id)
    if user is None:
        return _json_response({"message": "user not found"}, 404)
    return _json_response({"data": user}, 200)


@app.post("/v1/charge")
async def v1_charge(request: Request) -> Response:
    body = await _get_json_silent(request) or {}
    user_id = body.get("user_id")
    amount = body.get("amount")

    if not user_id:
        return _v1_headers(_json_response({"ok": False, "error": "user_id required"}, 200))
    if not isinstance(amount, int):
        return _v1_headers(_json_response({"ok": False, "error": "amount must be an integer"}, 200))
    balance = _BALANCES.get(user_id)
    if balance is None:
        return _v1_headers(_json_response({"ok": False, "error": "unknown user"}, 200))
    if amount > balance:
        return _v1_headers(_json_response({"ok": False, "error": "insufficient funds"}, 200))
    return _v1_headers(_json_response({"ok": True, "remaining": balance - amount}, 200))


@app.post("/v2/charge")
async def v2_charge(request: Request) -> Response:
    body = await _get_json_silent(request) or {}
    if "user_id" not in body:
        return _json_response({"message": "user_id required", "field": "user_id"}, 422)
    amount = body.get("amount")
    if not isinstance(amount, int):
        return _json_response({"message": "amount must be an integer", "field": "amount"}, 422)
    balance = _BALANCES.get(body["user_id"])
    if balance is None:
        return _json_response({"message": "unknown user"}, 404)
    if amount > balance:
        return _json_response({"message": "insufficient funds", "balance": balance}, 402)
    return _json_response({"remaining": balance - amount}, 200)


@app.get("/v1/ping")
def v1_ping() -> Response:
    return _v1_headers(Response(content="pong", status_code=200, media_type="text/html"))


@app.get("/v2/ping")
def v2_ping() -> Response:
    return _json_response("pong", 200)


@app.post("/v2/batch")
async def v2_batch(request: Request) -> Response:
    body = await _get_json_silent(request)
    if not isinstance(body, list):
        return _json_response({"message": "body must be a JSON array"}, 422)

    outcomes = []
    for index, entry in enumerate(body):
        if not isinstance(entry, dict) or "user_id" not in entry:
            outcomes.append({"index": index, "ok": False, "error": "malformed entry"})
        elif entry["user_id"] not in _USERS:
            outcomes.append({"index": index, "ok": False, "error": "unknown user"})
        else:
            outcomes.append({"index": index, "ok": True})

    failures = sum(1 for outcome in outcomes if not outcome["ok"])
    status = 200 if failures == 0 else 207
    return _json_response({"outcomes": outcomes, "failures": failures}, status)


@app.get("/v1/config")
def v1_config() -> Response:
    return _v1_headers(
        _json_response(
            {
                "deprecation": DEPRECATION,
                "deprecated": True,
                "isDeprecated": True,
                "tiers": ["free", "pro"],
            },
            200,
        )
    )
"}

{"code": "from __future__ import annotations

import json
from http import HTTPStatus
from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(redirect_slashes=False)

_ACCOUNTS = {"a1": {"id": "a1", "balance": 100}}


class InsufficientFunds(Exception):
    def __init__(self, needed: int, available: int):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


def _http_message(status_code: int) -> str:
    try:
        return HTTPStatus(status_code).phrase
    except ValueError:
        return "Unknown Error"


def _is_json_mimetype(content_type: str | None) -> bool:
    if not content_type:
        return False
    mimetype = content_type.split(";", 1)[0].strip().lower()
    return mimetype == "application/json" or (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    )


async def _get_json_silent(request: Request) -> Any:
    if not _is_json_mimetype(request.headers.get("content-type")):
        return None
    try:
        body = await request.body()
        return json.loads(body)
    except Exception:
        return None


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds):
    return JSONResponse(
        content={
            "error": "insufficient_funds",
            "needed": exc.needed,
            "available": exc.available,
        },
        status_code=409,
    )


@app.exception_handler(StarletteHTTPException)
async def on_http_error(request: Request, exc: StarletteHTTPException):
    return JSONResponse(
        content={
            "error": "http_error",
            "status": exc.status_code,
            "message": _http_message(exc.status_code),
        },
        status_code=exc.status_code,
    )


@app.exception_handler(Exception)
async def on_unhandled_error(request: Request, exc: Exception):
    return JSONResponse(
        content={
            "error": "http_error",
            "status": 500,
            "message": "Internal Server Error",
        },
        status_code=500,
    )


@app.get("/accounts/{account_id}")
async def get_account(account_id: str):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            content={"error": "not_found", "resource": "account"},
            status_code=404,
        )
    return JSONResponse(content=account)


@app.post("/accounts/{account_id}/withdraw")
async def withdraw(account_id: str, request: Request):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            content={"error": "not_found", "resource": "account"},
            status_code=404,
        )

    data = await _get_json_silent(request) or {}
    try:
        amount = data.get("amount")
    except AttributeError:
        return JSONResponse(
            content={
                "error": "http_error",
                "status": 500,
                "message": "Internal Server Error",
            },
            status_code=500,
        )

    if not isinstance(amount, int) or amount <= 0:
        return JSONResponse(content={"error": "bad_amount"}, status_code=400)

    if amount > account["balance"]:
        raise InsufficientFunds(amount, account["balance"])

    return JSONResponse(
        content={
            "id": account_id,
            "withdrawn": amount,
            "balance": account["balance"] - amount,
        }
    )
"}

{"code":""""FastAPI migration of the legacy Flask configuration/reporting app."""

import json
from typing import Any

from fastapi import Depends, FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from pydantic import BaseModel, ConfigDict


class AppConfig(BaseModel):
    model_config = ConfigDict(frozen=True)

    PAGE_SIZE: int = 3
    FEATURE_VERBOSE: bool = True
    SERVICE_NAME: str = "reporting"
    MAX_RANGE_DAYS: int = 30


_CONFIG = AppConfig()

_ROWS = [{"id": i, "value": i * 10} for i in range(1, 11)]


class FlaskJSONResponse(JSONResponse):
    """Render JSON close to Flask jsonify's compact default output."""

    media_type = "application/json"

    def render(self, content: Any) -> bytes:
        return (
            json.dumps(
                content,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")


app = FastAPI(default_response_class=FlaskJSONResponse, redirect_slashes=False)


def get_config() -> AppConfig:
    return _CONFIG


def _is_json_mimetype(content_type: str | None) -> bool:
    if not content_type:
        return False
    mimetype = content_type.split(";", 1)[0].strip().lower()
    return mimetype == "application/json" or (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    )


async def _get_json_silent(request: Request) -> Any:
    """Approximate Flask request.get_json(silent=True)."""
    if not _is_json_mimetype(request.headers.get("content-type")):
        return None

    body = await request.body()
    try:
        return json.loads(body)
    except Exception:
        return None


@app.exception_handler(Exception)
async def _flask_like_500_handler(request: Request, exc: Exception) -> HTMLResponse:
    body = (
        "<!doctype html>\n"
        "<html lang=en>\n"
        "<title>500 Internal Server Error</title>\n"
        "<h1>Internal Server Error</h1>\n"
        "<p>The server encountered an internal error and was unable to complete your request. "
        "Either the server is overloaded or there is an error in the application.</p>\n"
    )
    return HTMLResponse(content=body, status_code=500)


@app.get("/config", response_class=FlaskJSONResponse)
def show_config(config: AppConfig = Depends(get_config)) -> FlaskJSONResponse:
    return FlaskJSONResponse(
        content={
            "service": config.SERVICE_NAME,
            "page_size": config.PAGE_SIZE,
            "verbose": config.FEATURE_VERBOSE,
        }
    )


@app.get("/rows", response_class=FlaskJSONResponse)
def rows(
    request: Request,
    config: AppConfig = Depends(get_config),
) -> FlaskJSONResponse:
    raw_values = request.query_params.getlist("size")
    converted_size: int | None = None
    if raw_values:
        try:
            converted_size = int(raw_values[0])
        except (TypeError, ValueError):
            converted_size = None

    size = converted_size or config.PAGE_SIZE
    page = _ROWS[:size]
    payload: dict[str, Any] = {"rows": page}
    if config.FEATURE_VERBOSE:
        payload["meta"] = {"returned": len(page), "total": len(_ROWS)}
    return FlaskJSONResponse(content=payload)


@app.post("/report", response_class=FlaskJSONResponse)
