    if days > config.MAX_RANGE_DAYS:
        return FlaskJSONResponse(
            content={"error": "range too large", "max": config.MAX_RANGE_DAYS},
            status_code=400,
        )
    return FlaskJSONResponse(
        content={"service": config.SERVICE_NAME, "days": days},
        status_code=202,
    )
