from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(openapi_url=None, docs_url=None, redoc_url=None)

_EVENTS = [{"id": i, "kind": "click"} for i in range(1, 26)]
MAX_PER_PAGE = 10


class FlaskJSONResponse(JSONResponse):
    """Render JSON like Flask's jsonify in a default non-debug app."""

    def render(self, content: Any) -> bytes:
        return (
            json.dumps(
                content,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")


def _query_pairs(request: Request) -> list[tuple[str, str]]:
    raw_query = request.scope.get("query_string", b"")
    query = raw_query.decode("latin-1")
    return parse_qsl(query, keep_blank_values=True, encoding="utf-8", errors="replace")


def _get_int_arg(request: Request, name: str, default: int) -> int:
    # Werkzeug/Flask's request.args.get(..., type=int) uses the first value and
    # returns the default when conversion fails.
    for key, value in _query_pairs(request):
        if key == name:
            try:
                return int(value)
            except (TypeError, ValueError):
                return default
    return default


_FLASK_500_BODY = """<!doctype html>
<html lang=en>
<title>500 Internal Server Error</title>
<h1>Internal Server Error</h1>
<p>The server encountered an internal error and was unable to complete your request. Either the server is overloaded or there is an error in the application.</p>
"""

_FLASK_404_BODY = """<!doctype html>
<html lang=en>
<title>404 Not Found</title>
<h1>Not Found</h1>
<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>
"""

_FLASK_405_BODY = """<!doctype html>
<html lang=en>
<title>405 Method Not Allowed</title>
<h1>Method Not Allowed</h1>
<p>The method is not allowed for the requested URL.</p>
"""


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return HTMLResponse(content=_FLASK_404_BODY, status_code=404)
    if exc.status_code == 405:
        headers = getattr(exc, "headers", None)
        return HTMLResponse(content=_FLASK_405_BODY, status_code=405, headers=headers)
    return HTMLResponse(content=str(exc.detail), status_code=exc.status_code, headers=getattr(exc, "headers", None))


@app.exception_handler(Exception)
async def unhandled_exception_handler(request: Request, exc: Exception):
    return HTMLResponse(content=_FLASK_500_BODY, status_code=500)


@app.get("/events")
async def events(request: Request):
    page = _get_int_arg(request, "page", 1)
    per_page = _get_int_arg(request, "per_page", 5)

    if page < 1:
        return FlaskJSONResponse(content={"error": "page must be >= 1"}, status_code=400)
    if per_page > MAX_PER_PAGE:
        per_page = MAX_PER_PAGE

    start = (page - 1) * per_page
    rows = _EVENTS[start : start + per_page]
    total = len(_EVENTS)

    if per_page == 0:
        return HTMLResponse(content=_FLASK_500_BODY, status_code=500)

    last_page = (total + per_page - 1) // per_page

    links = [
        f'</events?page=1&per_page={per_page}>; rel="first"',
        f'</events?page={last_page}&per_page={per_page}>; rel="last"',
    ]
    if page < last_page:
        links.append(f'</events?page={page + 1}&per_page={per_page}>; rel="next"')

    headers = {
        "X-Total-Count": str(total),
        "Link": ", ".join(links),
    }
    return FlaskJSONResponse(
        content={"events": rows, "page": page, "per_page": per_page},
        status_code=200,
        headers=headers,
    )
"}

{"code":""""FastAPI migration of the legacy Flask trailing-slash behaviour example."""

import json
from html import escape
from typing import Any
from urllib.parse import urlsplit, urlunsplit

from fastapi import FastAPI, Request
from fastapi.responses import Response
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)
app.router.redirect_slashes = False


def flask_jsonify(content: Any, status_code: int = 200) -> Response:
    body = json.dumps(
        content,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ) + "\n"
    return Response(content=body, status_code=status_code, media_type="application/json")


def flask_html_error(status_code: int, title: str, heading: str, message: str, headers: dict[str, str] | None = None) -> Response:
    body = (
        "<!doctype html>\n"
        "<html lang=en>\n"
        f"<title>{status_code} {title}</title>\n"
        f"<h1>{heading}</h1>\n"
        f"<p>{message}</p>\n"
    )
    return Response(
        content=body,
        status_code=status_code,
        media_type="text/html; charset=utf-8",
        headers=headers,
    )


def flask_redirect(location: str, status_code: int = 308) -> Response:
    escaped_location = escape(location)
    body = (
        "<!doctype html>\n"
        "<html lang=en>\n"
        "<title>Redirecting...</title>\n"
        "<h1>Redirecting...</h1>\n"
        "<p>You should be redirected automatically to the target URL: "
        f"<a href=\"{escaped_location}\">{escaped_location}</a>. If not, click the link.\n"
    )
    return Response(
        content=body,
        status_code=status_code,
        media_type="text/html; charset=utf-8",
        headers={"Location": location},
    )


def add_trailing_slash_to_url(url: str) -> str:
    parts = urlsplit(url)
    return urlunsplit((parts.scheme, parts.netloc, parts.path + "/", parts.query, parts.fragment))


@app.middleware("http")
async def preserve_flask_slash_semantics(request: Request, call_next):
    # Flask strict_slashes redirects /reports -> /reports/ with status 308.
    if request.method == "GET" and request.url.path == "/reports":
        return flask_redirect(add_trailing_slash_to_url(str(request.url)), status_code=308)

    # The legacy /jobs route was declared strict_slashes=False, so /jobs/ is accepted too.
    if request.method == "GET" and request.url.path == "/jobs/":
        return flask_jsonify({"jobs": []})

    return await call_next(request)


@app.exception_handler(StarletteHTTPException)
async def preserve_flask_http_errors(request: Request, exc: StarletteHTTPException) -> Response:
    if exc.status_code == 404:
        return flask_html_error(
            404,
            "Not Found",
            "Not Found",
            "The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.",
        )
    if exc.status_code == 405:
        return flask_html_error(
            405,
            "Method Not Allowed",
            "Method Not Allowed",
            "The method is not allowed for the requested URL.",
            headers=dict(exc.headers or {}),
        )
    return flask_html_error(
        exc.status_code,
        str(exc.detail),
        str(exc.detail),
        str(exc.detail),
        headers=dict(exc.headers or {}),
    )


@app.get("/reports/")
def list_reports() -> Response:
    return flask_jsonify({"reports": ["daily", "weekly"]})


@app.get("/status")
def status() -> Response:
    return flask_jsonify({"status": "up"})


@app.get("/jobs")
def jobs() -> Response:
    return flask_jsonify({"jobs": []})


@app.get("/queue/{name}")
def queue(name: str) -> Response:
    return flask_jsonify({"queue": name, "depth": 0})
"}

