{"code": "import json
from email import policy
from email.parser import BytesParser
from http import HTTPStatus
from typing import Optional
from urllib.parse import parse_qs

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException


app = FastAPI()

todos = {}

_BAD_REQUEST_MESSAGE = "The browser (or proxy) sent a request that this server could not understand."
_NOT_FOUND_HTML = """<!doctype html>\n<html lang=en>\n<title>404 Not Found</title>\n<h1>Not Found</h1>\n<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>\n"""


class FlaskRestfulJSONResponse(JSONResponse):
    media_type = "application/json"

    def render(self, content) -> bytes:
        return (json.dumps(content) + "\n").encode("utf-8")


def _json_response(content, status_code: int = 200, headers: Optional[dict] = None) -> FlaskRestfulJSONResponse:
    return FlaskRestfulJSONResponse(content=content, status_code=status_code, headers=headers)


def _first_urlencoded_value(body: bytes, name: str) -> Optional[str]:
    parsed = parse_qs(body.decode("utf-8", errors="replace"), keep_blank_values=True)
    values = parsed.get(name)
    if not values:
        return None
    return values[0]


def _first_multipart_value(body: bytes, content_type: str, name: str) -> Optional[str]:
    try:
        raw_message = (
            f"Content-Type: {content_type}\r\nMIME-Version: 1.0\r\n\r\n".encode("utf-8") + body
        )
        message = BytesParser(policy=policy.default).parsebytes(raw_message)
        if not message.is_multipart():
            return None

        for part in message.iter_parts():
            params_list = part.get_params(header="content-disposition", unquote=True) or []
            if not params_list:
                continue
            disposition = (params_list[0][0] or "").lower()
            params = {k.lower(): v for k, v in params_list[1:]}
            if disposition == "form-data" and params.get("name") == name and "filename" not in params:
                value = part.get_content()
                if isinstance(value, bytes):
                    return value.decode("utf-8", errors="replace")
                return value
    except Exception:
        return None
    return None


async def _request_form_data_value(request: Request) -> Optional[str]:
    content_type = request.headers.get("content-type", "")
    media_type = content_type.split(";", 1)[0].strip().lower()
    body = await request.body()

    if media_type == "application/x-www-form-urlencoded":
        return _first_urlencoded_value(body, "data")
    if media_type == "multipart/form-data":
        return _first_multipart_value(body, content_type, "data")
    return None


@app.get("/{todo_id}")
async def get_todo(todo_id: str):
    try:
        return _json_response({todo_id: todos[todo_id]})
    except KeyError:
        return _json_response({"message": "Internal Server Error"}, status_code=500)


@app.put("/{todo_id}")
async def put_todo(todo_id: str, request: Request):
    value = await _request_form_data_value(request)
    if value is None:
        return _json_response({"message": _BAD_REQUEST_MESSAGE}, status_code=400)

    todos[todo_id] = value
    return _json_response({todo_id: todos[todo_id]})


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return HTMLResponse(content=_NOT_FOUND_HTML, status_code=404)
    if exc.status_code == 405:
        return _json_response(
            {"message": "The method is not allowed for the requested URL."},
            status_code=405,
            headers=exc.headers,
        )
    message = HTTPStatus(exc.status_code).phrase if exc.status_code in HTTPStatus._value2member_map_ else str(exc.detail)
    return _json_response({"message": message}, status_code=exc.status_code, headers=exc.headers)


@app.exception_handler(Exception)
async def unhandled_exception_handler(request: Request, exc: Exception):
    return _json_response({"message": "Internal Server Error"}, status_code=500)
"}

{"code":""""FastAPI migration of the legacy Flask order lifecycle module."""

import json
from typing import Any, Dict, List, Optional, Set

from fastapi import Depends, FastAPI, Request
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel, ConfigDict

app = FastAPI(redirect_slashes=False)

TRANSITIONS = {
    "draft": ["submitted", "cancelled"],
    "submitted": ["approved", "rejected", "cancelled"],
    "approved": ["fulfilled"],
    "rejected": [],
    "cancelled": [],
    "fulfilled": [],
}
TERMINAL = {"rejected", "cancelled", "fulfilled"}

_ORDERS = {
    "o1": {"id": "o1", "state": "draft", "total": 30, "lines": 2},
    "o2": {"id": "o2", "state": "approved", "total": 90, "lines": 5},
}
_IDEMPOTENCY = {}
_NEXT = [3]


class Settings(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)

    transitions: Dict[str, List[str]]
    terminal: Set[str]


_SETTINGS = Settings(transitions=TRANSITIONS, terminal=TERMINAL)


def get_settings() -> Settings:
    return _SETTINGS


class FlaskJSONResponse(JSONResponse):
    def render(self, content: Any) -> bytes:
        return (
            json.dumps(
                content,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")


def jsonify(content: Any, status_code: int = 200, headers: Optional[Dict[str, str]] = None) -> FlaskJSONResponse:
    return FlaskJSONResponse(content=content, status_code=status_code, headers=headers)


def _is_json_content_type(content_type: Optional[str]) -> bool:
    if not content_type:
        return False
    mimetype = content_type.split(";", 1)[0].strip().lower()
    return mimetype == "application/json" or (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    )


async def _get_json_silent(request: Request) -> Any:
    if not _is_json_content_type(request.headers.get("content-type")):
        return None
    try:
        body = await request.body()
        return json.loads(body)
    except Exception:
        return None


def _first_query_arg(request: Request, name: str) -> Optional[str]:
    values = request.query_params.getlist(name)
    return values[0] if values else None


def _present(order: Dict[str, Any], settings: Settings) -> Dict[str, Any]:
    return {**order, "terminal": order["state"] in settings.terminal}


@app.get("/orders/{order_id}")
def get_order(order_id: str, settings: Settings = Depends(get_settings)):
    order = _ORDERS.get(order_id)
    if order is None:
        return jsonify({"error": "order not found", "id": order_id}, 404)
    return jsonify(_present(order, settings))


@app.post("/orders")
async def create_order(request: Request, settings: Settings = Depends(get_settings)):
    body = await _get_json_silent(request) or {}
    total = body.get("total")
    if not isinstance(total, int) or total <= 0:
        return jsonify({"error": "total must be a positive integer"}, 400)

    key = request.headers.get("Idempotency-Key")
    if key:
        seen = _IDEMPOTENCY.get(key)
        if seen is not None:
            if seen["total"] != total:
                return jsonify(
                    {
                        "error": "idempotency key reused with a different body",
                        "code": "IDEMPOTENCY_MISMATCH",
                    },
                    422,
                )
            return jsonify(_present(_ORDERS[seen["id"]], settings), 200)

    order_id = f"o{_NEXT[0]}"
    _NEXT[0] += 1
    order = {"id": order_id, "state": "draft", "total": total, "lines": body.get("lines", 1)}
    _ORDERS[order_id] = order
    if key:
        _IDEMPOTENCY[key] = {"id": order_id, "total": total}

    return jsonify(_present(order, settings), 201, headers={"Location": f"/orders/{order_id}"})


@app.post("/orders/{order_id}/transition")
async def transition(order_id: str, request: Request, settings: Settings = Depends(get_settings)):
    order = _ORDERS.get(order_id)
    if order is None:
        return jsonify({"error": "order not found", "id": order_id}, 404)

    body = await _get_json_silent(request) or {}
    target = body.get("to")
    if not target:
        return jsonify({"error": "to is required"}, 400)
    if target not in settings.transitions:
        return jsonify({"error": "unknown state", "state": target}, 400)

    allowed = settings.transitions[order["state"]]
    if target not in allowed:
        return jsonify(
            {
                "error": "illegal transition",
                "from": order["state"],
                "to": target,
                "allowed": allowed,
            },
            409,
        )

    order["state"] = target
    return jsonify(_present(order, settings))


@app.delete("/orders/{order_id}")
def delete_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return jsonify({"error": "order not found", "id": order_id}, 404)
    if order["state"] != "draft":
        return jsonify(
            {
                "error": "only draft orders can be deleted",
                "state": order["state"],
                "code": "NOT_DELETABLE",
            },
            409,
        )
    return Response(content="", status_code=204, media_type="text/html")


@app.get("/orders")
def list_orders(request: Request, settings: Settings = Depends(get_settings)):
    state = _first_query_arg(request, "state")
    rows = list(_ORDERS.values())
    if state:
        if state not in settings.transitions:
            return jsonify({"error": "unknown state", "state": state}, 400)
        rows = [o for o in rows if o["state"] == state]
    return jsonify({"orders": [_present(o, settings) for o in rows], "count": len(rows)})
"}
